using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class CalculateLoyaltyDiscountAcceptanceTests
{
    private static int ChargedFor(int subtotalCents, LoyaltyTier tier) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // S1 Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeBasketOf10000CentsIsChargedBronzePrice() =>
        Assert.Equal(9500, ChargedFor(10000, LoyaltyTier.Bronze));

    // S2 Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverBasketOf10000CentsIsChargedSilverPrice() =>
        Assert.Equal(9000, ChargedFor(10000, LoyaltyTier.Silver));

    // S3 Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldBasketOf10000CentsIsChargedGoldPrice() =>
        Assert.Equal(8500, ChargedFor(10000, LoyaltyTier.Gold));

    // S4 Bronze customer with a tiny basket is charged on a whole cent
    [Fact]
    public void S4_BronzeBasketOf7CentsIsCharged7Cents() =>
        Assert.Equal(7, ChargedFor(7, LoyaltyTier.Bronze));
}

